/* Apply to an SVG path with the checkmark path data. */
@keyframes demoStrokeDraw{from{stroke-dashoffset:70}to{stroke-dashoffset:0}}
.check-path{stroke-dasharray:70;stroke-dashoffset:0;animation:demoStrokeDraw 850ms ease-out both;}

/* A real counter updates text, not just opacity or position. */
.number {font-variant-numeric: tabular-nums;}
